const g = $('VoltCare: indicadores globales').first().json;
const sw = $('VoltCare: correctivos de software (junior)').first().json;
const pv = $('VoltCare: preventivos').first().json;
const t = $input.first().json;
const h = (n) => `${Number(n).toLocaleString('es-AR', { maximumFractionDigits: 1 })} h`;
const filas = (t.abiertos ?? [])
  .map((c) => `<tr><td>${c.cliente}</td><td>${c.tipo_contrato}</td><td>${c.ultimo_preventivo ?? 'sin registro'}</td><td align="right">${c.dias_sin_preventivo ?? '-'}</td></tr>`)
  .join('');
const tiempos = g.contratos?.tiempo ?? {};
const html =
  `<h3>Resumen semanal de mantenimiento</h3>` +
  `<p>Indicadores de VoltCare sobre ${Number(g.records_analyzed).toLocaleString('es-AR')} tickets:</p>` +
  `<ul>` +
  `<li>MTTR global: <b>${h(g.mttr)}</b></li>` +
  `<li>MTTR preventivos: <b>${h(pv.mttr)}</b></li>` +
  `<li>MTTR correctivos de software con técnicos junior: <b>${h(sw.mttr)}</b></li>` +
  `<li>MTTR por contrato: suscripción ${h(tiempos['Suscripcion'])}, pay-per-use ${h(tiempos['Pay-per-use'])}</li>` +
  `</ul>` +
  `<p>${(g.insights ?? []).map((i) => `<i>${i}</i>`).join('<br>')}</p>` +
  `<h4>Clientes con más de ${t.preventivo_dias} días sin servicio preventivo</h4>` +
  `<p>Tickets de contacto nuevos esta semana: <b>${t.tickets_nuevos}</b>.</p>` +
  `<table border="1" cellpadding="6" cellspacing="0"><tr><th>Cliente</th><th>Contrato</th><th>Último preventivo</th><th>Días</th></tr>${filas}</table>`;
return [{ json: { clave: t.clave, para: t.email_gerencia, asunto: `Resumen semanal de mantenimiento (${t.tickets_nuevos} ticket(s) nuevo(s))`, html }, pairedItem: { item: 0 } }];
